const categoryLabels = { direct_hiring: 'Direct hiring', software_request: 'Software request', employee_referral: 'Employee referral', firsthand_announcement: 'Firsthand announcement', aggregated_listing: 'Aggregated listing', uncertain: 'Uncertain' };
