function marketFacetMarkup(items, labels = {}) { return items.length ? items.map((item) => `<button type="button" class="facet-button" data-facet-value="${esc(item.value)}"><span>${esc(labels[item.value] || item.value)}</span><span class="facet-count">${Number(item.count).toLocaleString()}</span></button>`).join('') : '<p class="subtle">No observed values.</p>'; }
