async function loadCompanies(resetPage = false) { if (resetPage) state.companyPage = 0; const pageSize = 50; const params = new URLSearchParams({sort:$('#company-sort').value, limit:String(pageSize), offset:String((state.companyPage || 0) * pageSize)}); for (const [id, key] of [['company-search','q'],['company-provider','provider'],['company-specialty','specialty'],['company-remote','remote'],['company-contract','contract'],['company-directory-prospect-status','prospectStatus']]) if ($(`#${id}`)?.value) params.set(key, $(`#${id}`).value); const data = await api(`/api/companies?${params}`); state.companyTotal = data.total; $('#companies').innerHTML = data.companies.length ? data.companies.map(companyCard).join('') : '<div class="empty"><p>No companies match these filters.</p><p class="subtle">Companies appear as ATS boards are added or discovered.</p></div>'; $('#company-pagination').innerHTML = paginationMarkup('companies', data.total, state.companyPage || 0, pageSize); document.querySelectorAll('#companies .company-card').forEach((card) => card.addEventListener('click', () => openCompany(card.dataset.companyId).catch(console.error))); document.querySelectorAll('#company-pagination .pagination-button').forEach((button) => button.addEventListener('click', () => { state.companyPage = Number(button.dataset.page); loadCompanies().catch(console.error); })); }
