function paginationMarkup(kind, total, page, pageSize) { const pages = Math.ceil(total / pageSize); if (pages <= 1) return ''; return `<span class="subtle">Page ${page + 1} of ${pages} · ${total.toLocaleString()} total</span><div><button class="button secondary pagination-button" data-kind="${kind}" data-page="${Math.max(0, page - 1)}" ${page === 0 ? 'disabled' : ''}>Previous</button><button class="button secondary pagination-button" data-kind="${kind}" data-page="${Math.min(pages - 1, page + 1)}" ${page >= pages - 1 ? 'disabled' : ''}>Next</button></div>`; }
