function compensationSummary(item) { const min = item.compensation_min !== null && item.compensation_min !== undefined && item.compensation_min !== '' ? Number(item.compensation_min) : undefined; const max = item.compensation_max !== null && item.compensation_max !== undefined && item.compensation_max !== '' ? Number(item.compensation_max) : undefined; const currency = item.compensation_currency || ''; const format = (value) => Number.isFinite(value) ? `${currency}${Math.round(value).toLocaleString()}` : ''; const range = min !== undefined && max !== undefined && min !== max ? `${format(min)}–${format(max)}` : format(max ?? min); const period = item.compensation_period ? ` / ${item.compensation_period}` : ''; if (range) return `${range}${period}${item.compensation_estimated ? ' (estimated)' : ''}`; const raw = typeof item.compensation === 'object' ? item.compensation?.description : ''; return raw || '' ; }
function listingCard(item) { const apply = item.application_url || item.original_url; const company = item.company_name || item.employer_name; const salary = compensationSummary(item); return `<article class="listing-card" data-id="${esc(item.id)}"><div class="opp-top"><div><span class="source-label">${esc(item.provider)} · <a href="#" class="company-link" data-company-id="${esc(item.employer_id)}">${esc(company)}</a></span><h2 class="listing-title">${esc(item.title)}</h2></div></div><div class="opp-meta"><span>${esc(item.location || 'Location not specified')}</span><span>${esc(workModeLabels[item.remote_mode] || 'Work mode unknown')}</span><span>${esc(item.employment_type || 'Employment type unknown')}</span>${salary ? `<span>${esc(salary)}</span>` : ''}<span>${esc(item.status)}</span></div><div class="badges"><span class="pill location-fit-${esc(item.location_fit)}">${esc(locationFitLabels[item.location_fit] || item.location_fit)} · ${Number(item.location_fit_score)}/100</span>${item.department ? `<span class="pill">${esc(item.department)}</span>` : ''}${item.seniority ? `<span class="pill">${esc(item.seniority)}</span>` : ''}</div><p class="subtle listing-date">Updated ${date(item.source_updated_at || item.last_observed_at)}</p><div class="listing-actions"><a class="button primary source-link" href="${esc(apply)}" target="_blank" rel="noreferrer" onclick="event.stopPropagation()">Apply / view source ↗</a><button class="button secondary listing-action" data-id="${esc(item.id)}" data-status="${item.status === 'saved' ? 'new' : 'saved'}">${item.status === 'saved' ? 'Unsave' : 'Save'}</button><button class="button secondary listing-action" data-id="${esc(item.id)}" data-status="${item.status === 'applied' ? 'new' : 'applied'}">${item.status === 'applied' ? 'Mark new' : 'Applied'}</button><button class="button secondary listing-action" data-id="${esc(item.id)}" data-status="dismissed">Dismiss</button></div></article>`; }
async function openListing(id) { const item = await api(`/api/listings/${id}`); const signals = typeof item.location_signals === 'string' ? JSON.parse(item.location_signals) : (item.location_signals || {}); const reasons = typeof item.location_fit_reasons === 'string' ? JSON.parse(item.location_fit_reasons) : (item.location_fit_reasons || []); const apply = item.application_url || item.original_url; const company = item.company_name || item.employer_name; const salary = compensationSummary(item); const history = (item.events || []).map((event) => `<div class="health-row"><span>${esc(event.event_type.replaceAll('_', ' '))}</span><span class="subtle">${date(event.observed_at)}</span></div>`).join('') || '<p class="subtle">No changes recorded yet. Initial board imports are treated as baselines.</p>'; $('#drawer-content').innerHTML = `<p class="eyebrow">${esc(item.provider)} · ${esc(company)}</p><h2 class="detail-title">${esc(item.title)}</h2><div class="badges"><span class="pill location-fit-${esc(item.location_fit)}">${esc(locationFitLabels[item.location_fit] || item.location_fit)} · ${Number(item.location_fit_score)}/100</span>${salary ? `<span class="pill">${esc(salary)}</span>` : ''}</div><p class="detail-text">${esc(item.description || 'No description supplied.')}</p><div class="detail-actions"><a class="button primary source-link" href="${esc(apply)}" target="_blank" rel="noreferrer">Apply / view source ↗</a><button class="button secondary listing-action" data-id="${esc(item.id)}" data-status="saved">Save</button></div>${locationDetails(signals, item.location_fit, item.location_fit_score, reasons)}<div class="detail-section"><h3>Source</h3><p><a class="source-link" href="${esc(item.original_url || apply)}" target="_blank" rel="noreferrer">${esc(item.original_url || apply)} ↗</a></p><p class="subtle">${esc(company)} · ${esc(item.board_identifier)} · ${date(item.source_updated_at || item.last_observed_at)}</p></div><div class="detail-section"><h3>Listing history</h3>${history}</div>`; $('#drawer').classList.remove('hidden'); document.querySelectorAll('#drawer .listing-action').forEach((button) => button.addEventListener('click', async () => { await api(`/api/listings/${button.dataset.id}`, {method:'PATCH', body:JSON.stringify({status:button.dataset.status})}); $('#drawer').classList.add('hidden'); await loadListings(); })); }
async function loadDiscoveryJobs() { const data = await api('/api/listing-discovery/jobs?limit=1'); const job = data.jobs[0]; if (!job) { $('#discovery-status').textContent = 'ATS board discovery has not run yet.'; return; } const cursor = typeof job.cursor === 'string' ? JSON.parse(job.cursor) : (job.cursor || {}); const phaseLabels = {extracting_posts:'extracting ATS links from Posts', collecting_archive:'scanning archive indexes', validating:'validating public ATS boards', waiting_retry:'waiting to retry', waiting_validation:'waiting for next validation batch', completed:'finished'}; const phase = phaseLabels[cursor.phase] || cursor.phase || 'starting'; const progress = cursor.phase === 'validating' ? ` · batch ${cursor.validationProcessed || 0}/${cursor.validationTotal || 0}` : cursor.phase === 'collecting_archive' ? ` · ${cursor.archiveRowsSeen || 0} archive rows · ${cursor.archiveCandidatesFound || 0} candidates${cursor.archiveLastUrl ? ` · last ${cursor.archiveLastUrl}` : ''}` : ''; const provider = cursor.currentProvider ? ` · ${cursor.currentProvider}` : ''; const update = job.updated_at ? ` · updated ${relative(job.updated_at)}` : ''; $('#discovery-status').textContent = `ATS discovery: ${job.status} · ${phase}${provider}${progress} · ${job.candidates_seen || 0} candidates · ${job.candidates_validated || 0} validated · ${job.boards_imported || 0} boards imported${update}${job.last_error ? ` · ${job.last_error}` : ''}`; }
async function loadBoards(resetPage = false) { if (resetPage) state.boardPage = 0; const pageSize = 50; const data = await api(`/api/job-boards?limit=${pageSize}&offset=${state.boardPage * pageSize}`); state.boardTotal = data.total; $('#boards').innerHTML = data.boards.length ? data.boards.map((board) => `<div class="board-row"><div><strong>${esc(board.employer_name)}</strong><div class="subtle">${esc(board.provider)} · ${esc(board.board_identifier)} · ${board.active_listing_count} active listings</div><div class="subtle">${board.last_successful_poll ? `Last poll ${date(board.last_successful_poll)}` : 'Waiting for first poll'}${board.last_error ? ` · <span class="error-text">${esc(board.last_error)}</span>` : ''}</div></div><div class="board-actions"><span class="pill">${esc(board.status)}</span><button class="button secondary board-toggle" data-id="${board.id}" data-status="${board.status === 'active' ? 'disabled' : 'active'}">${board.status === 'active' ? 'Disable' : 'Enable'}</button></div></div>`).join('') : '<p class="subtle">No career boards configured yet.</p>'; $('#board-pagination').innerHTML = paginationMarkup('boards', state.boardTotal, state.boardPage, pageSize); document.querySelectorAll('#board-pagination .pagination-button').forEach((button) => button.addEventListener('click', () => { state.boardPage = Number(button.dataset.page); loadBoards().catch(console.error); })); document.querySelectorAll('.board-toggle').forEach((button) => button.addEventListener('click', async () => { await api(`/api/job-boards/${button.dataset.id}`, {method:'PATCH', body:JSON.stringify({status:button.dataset.status})}); await loadBoards(); await loadListings(); })); }
function hideDepartmentOptions() { $('#listing-department-options')?.classList.add('hidden'); }
