async function searchDepartments(search = '') { const request = ++departmentSearchRequest; const query = search.trim(); const data = await api(`/api/listing-departments?limit=25${query ? `&q=${encodeURIComponent(query)}` : ''}`); if (request === departmentSearchRequest) renderDepartmentOptions(data.departments); }
function setupDepartmentCombobox() { const input = $('#listing-department'); if (!input) return; input.addEventListener('focus', () => searchDepartments(input.value).catch(console.error)); input.addEventListener('input', () => { clearTimeout(departmentSearchTimer); const value = input.value; departmentSearchTimer = setTimeout(() => { if (!value.trim()) { hideDepartmentOptions(); loadListings(true).catch(console.error); } else searchDepartments(value).catch(console.error); }, 220); }); input.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); hideDepartmentOptions(); loadListings(true).catch(console.error); } if (event.key === 'Escape') hideDepartmentOptions(); }); document.addEventListener('click', (event) => { if (!event.target.closest('.department-combobox')) hideDepartmentOptions(); }); }
function scheduleListingsRefresh() { if (!$('#view-listings').classList.contains('active') || listingRefreshTimer) return; listingRefreshTimer = setTimeout(() => { listingRefreshTimer = undefined; if (listingRefreshInFlight) { listingRefreshRequested = true; return; } listingRefreshInFlight = true; loadListings().catch(console.error).finally(() => { listingRefreshInFlight = false; if (listingRefreshRequested) { listingRefreshRequested = false; scheduleListingsRefresh(); } }); }, 5000); }
async function loadPollTasks() { const data = await api('/api/listing-poll-tasks?limit=500&historyLimit=100'); const active = data.active || []; const completed = data.history || []; const running = active.filter((task) => task.status === 'running').length; const queued = active.length - running; const taskRow = (task) => `<div class="task-row"><div><strong>${esc(task.employer_name)}</strong><div class="subtle">${esc(task.provider)} · ${esc(task.board_identifier)}</div><div class="health-detail">${task.status === 'queued' ? `Queue position ${task.queue_position} · queued ${date(task.queued_at)}` : task.status === 'running' ? `Current task · started ${date(task.started_at)}` : `${task.listings_seen || 0} listings · ${task.new_listings || 0} new · ${task.duration_ms ? `${Math.round(task.duration_ms / 1000)}s` : '—'} · ${date(task.completed_at)}`}${task.error ? ` · <span class="error-text">${esc(task.error)}</span>` : ''}</div></div><span class="pill task-${esc(task.status)}">${esc(task.status)}</span></div>`; $('#poll-tasks').innerHTML = `<div class="task-panel-grid"><div class="task-card"><div class="task-heading"><div><h2>Polling queue</h2><p class="subtle">${running} running · ${queued} queued · bounded concurrency</p></div><button id="refresh-poll-tasks" class="button secondary" type="button">Refresh</button></div>${active.length ? active.map(taskRow).join('') : '<p class="subtle">No polling tasks are currently queued.</p>'}</div><div class="task-card"><h2>Completed task history</h2><p class="subtle">Latest ${completed.length} completed or failed tasks</p>${completed.length ? completed.map(taskRow).join('') : '<p class="subtle">No completed polling tasks yet.</p>'}</div></div>`; $('#refresh-poll-tasks')?.addEventListener('click', () => loadPollTasks().catch(console.error)); }
function ensureLocationSettings() { if ($('#location-fit-threshold')) return; document.querySelector('#settings-form .settings-card').insertAdjacentHTML('beforeend', '<h2>Location fit</h2><p class="subtle">Tune compatibility with your saved location and timezone.</p><label>Minimum post notification fit score<input id="location-fit-threshold" type="number" min="0" max="100" value="40"></label><label>Base location<input id="base-location"></label><label>Base timezone<input id="base-timezone"></label><label>UTC offset<input id="base-utc-offset" type="number" min="-12" max="14" value="0"></label><label>Preferred regions<textarea id="preferred-regions"></textarea></label>'); }
function ensureListingSettings() { if ($('#listings-notifications-enabled')) return; document.querySelector('#settings-form .settings-card').insertAdjacentHTML('beforeend', '<h2>Listings notifications</h2><label class="switch-row"><input name="listingsNotificationsEnabled" id="listings-notifications-enabled" type="checkbox"><span>Send listing notifications</span></label><label>Minimum listing location fit<input name="minimumListingLocationFitScore" id="listing-location-threshold" type="number" min="0" max="100" value="40"></label>'); }
function loadSettings() { ensureLocationSettings(); ensureListingSettings(); return api('/api/settings').then((data) => { state.settings = data.preferences; const p = data.preferences; $('#threshold').value = p.minimumNotificationScore; $('#threshold-output').textContent = p.minimumNotificationScore; $('#quality-threshold').value = p.minimumNotificationSignalQuality; $('#relevance-threshold').value = p.minimumNotificationPersonalRelevance; $('#location-fit-threshold').value = p.minimumNotificationLocationFitScore; $('#base-location').value = p.locationProfile?.baseLocation || ''; $('#base-timezone').value = p.locationProfile?.timeZone || ''; $('#base-utc-offset').value = p.locationProfile?.utcOffset ?? 0; $('#preferred-regions').value = (p.locationProfile?.preferredRegions || []).join(', '); $('#notifications-enabled').checked = p.notificationsEnabled; $('#notify-recovered').checked = p.notifyRecovered; $('#listings-notifications-enabled').checked = p.listingsNotificationsEnabled; $('#listing-location-threshold').value = p.minimumListingLocationFitScore; ['technologyTerms','roleTerms','remoteTerms','internationalTerms','contractTerms','contactTerms'].forEach((key) => document.querySelector(`[name="${key}"]`).value = (p[key] || []).join(', ')); document.querySelector('[name="weights"]').value = JSON.stringify(p.weights || {}, null, 2); if (data.devMode) $('#sample-btn').classList.remove('hidden'); }); }
function settingsPayload() { const fields = ['technologyTerms','roleTerms','remoteTerms','internationalTerms','contractTerms','contactTerms']; const payload = {minimumNotificationScore:Number($('#threshold').value), minimumNotificationSignalQuality:Number($('#quality-threshold').value), minimumNotificationPersonalRelevance:Number($('#relevance-threshold').value), minimumNotificationLocationFitScore:Number($('#location-fit-threshold').value), notificationsEnabled:$('#notifications-enabled').checked, notifyRecovered:$('#notify-recovered').checked, listingsNotificationsEnabled:$('#listings-notifications-enabled').checked, minimumListingLocationFitScore:Number($('#listing-location-threshold').value), locationProfile:{baseLocation:$('#base-location').value.trim(),timeZone:$('#base-timezone').value.trim(),utcOffset:Number($('#base-utc-offset').value),preferredRegions:$('#preferred-regions').value.split(',').map((term) => term.trim()).filter(Boolean)}}; for (const key of fields) payload[key] = document.querySelector(`[name="${key}"]`).value.split(',').map((term) => term.trim()).filter(Boolean); try { payload.weights = JSON.parse(document.querySelector('[name="weights"]').value || '{}'); } catch { throw new Error('Category weights must be valid JSON'); } return payload; }
async function loadMonitoring() { const data = await api('/api/monitoring'); const discovery = data.discovery; const discoveryCursor = discovery ? (typeof discovery.cursor === 'string' ? JSON.parse(discovery.cursor) : (discovery.cursor || {})) : {}; const archiveProgress = discoveryCursor.phase === 'collecting_archive' ? `<div class="health-detail">${discoveryCursor.archiveRowsSeen || 0} archive rows · ${discoveryCursor.archiveCandidatesFound || 0} candidates${discoveryCursor.archiveLastUrl ? ` · last ${esc(discoveryCursor.archiveLastUrl)}` : ''}</div>` : ''; $('#monitoring').innerHTML = `<div class="monitor-card"><h2>Ingestion sources</h2>${data.sources.map((source) => `<div class="health-row"><div><strong>${esc({bluesky:'Bluesky Jetstream', hacker_news:'Hacker News API', mastodon:'Mastodon public stream', reddit:'Reddit API'}[source.source] || source.source)}</strong><div class="health-detail">${source.processed_count} processed · ${source.matched_count} matched · ${source.threshold_count} above notification thresholds</div>${source.last_error ? `<div class="health-detail error-text">${esc(source.last_error)}</div>` : ''}</div><span class="health-status ${source.last_success_at && new Date(source.last_success_at).getTime() > Date.now() - 5 * 60 * 1000 ? '' : 'off'}">${source.last_success_at && new Date(source.last_success_at).getTime() > Date.now() - 5 * 60 * 1000 ? 'Healthy' : 'Waiting'}</span></div>`).join('')}</div><div class="monitor-card"><h2>Listings pipeline</h2><div class="health-row"><span>Boards</span><strong>${data.listingBoards.active} active / ${data.listingBoards.total} total</strong></div><div class="health-row"><span>Active listings</span><strong>${data.listingCounts.active}</strong></div><div class="health-row"><span>Good location fit</span><strong>${data.listingCounts.good_location}</strong></div><div class="health-row"><span>Board failures</span><strong class="${data.listingBoards.failing ? 'health-status off' : ''}">${data.listingBoards.failing}</strong></div></div><div class="monitor-card"><h2>ATS board discovery</h2>${discovery ? `<div class="health-row"><span>Status</span><strong>${esc(discovery.status)}</strong></div><div class="health-row"><span>Phase</span><strong>${esc(discoveryCursor.phase || 'starting')}${discoveryCursor.currentProvider ? ` · ${esc(discoveryCursor.currentProvider)}` : ''}</strong></div>${archiveProgress}<div class="health-row"><span>Candidates</span><strong>${discovery.candidate_count} seen · ${discovery.candidates_validated} validated</strong></div><div class="health-row"><span>Boards imported</span><strong>${discovery.imported_count}</strong></div><div class="health-detail">Last database update ${relative(discovery.updated_at)}</div>${discovery.last_error ? `<div class="health-detail error-text">${esc(discovery.last_error)}</div>` : ''}` : '<p class="subtle">No discovery job has run yet.</p>'}</div><div class="monitor-card"><h2>Notifications</h2><div class="health-row"><span>SMTP configuration</span><strong class="health-status ${data.smtpConfigured ? '' : 'off'}">${data.smtpConfigured ? 'Configured' : 'Not configured'}</strong></div><div class="health-row"><span>Post notifications sent</span><strong>${data.notifications.sent}</strong></div><div class="health-row"><span>Listing notifications sent</span><strong>${data.listingNotifications.sent}</strong></div><div class="health-row"><span>Pending / retrying</span><strong>${Number(data.notifications.pending) + Number(data.listingNotifications.pending)}</strong></div></div>`; }
function connectEvents() { const source = new EventSource('/api/events'); source.addEventListener('opportunity', () => { $('#live-dot').classList.add('on'); $('#live-label').textContent = 'live'; loadFeed().catch(console.error); }); source.addEventListener('listings', () => { $('#live-dot').classList.add('on'); $('#live-label').textContent = 'live'; scheduleListingsRefresh(); if ($('#view-polling').classList.contains('active')) loadPollTasks().catch(console.error); }); source.addEventListener('listing-task', () => { if ($('#view-polling').classList.contains('active')) loadPollTasks().catch(console.error); }); source.addEventListener('listing-discovery', () => { if ($('#view-listings').classList.contains('active')) loadDiscoveryJobs().catch(console.error); }); source.addEventListener('health', () => { $('#live-dot').classList.add('on'); $('#live-label').textContent = 'live'; }); source.onerror = () => { $('#live-dot').classList.remove('on'); $('#live-label').textContent = 'reconnecting'; }; }
document.querySelectorAll('.tab').forEach((tab) => tab.addEventListener('click', async () => { document.querySelectorAll('.tab').forEach((item) => item.classList.toggle('active', item === tab)); document.querySelectorAll('.view').forEach((view) => view.classList.toggle('active', view.id === `view-${tab.dataset.view}`)); if (tab.dataset.view === 'market') await loadMarket(); if (tab.dataset.view === 'companies') await loadCompanies(true); if (tab.dataset.view === 'polling') await loadPollTasks(); if (tab.dataset.view === 'monitoring') await loadMonitoring(); if (tab.dataset.view === 'rules') await loadRules(); if (tab.dataset.view === 'authors') await loadAuthors(); if (tab.dataset.view === 'settings') await loadSettings(); }));
['sort','source-filter','category-filter','status-filter'].forEach((id) => $(`#${id}`).addEventListener('change', () => loadFeed().catch((error) => alert(error.message)))); $('#apply-feed-filter').addEventListener('click', () => loadFeed().catch((error) => alert(error.message))); $('#refresh-btn').addEventListener('click', () => loadFeed().catch(console.error)); $('#close-drawer').addEventListener('click', () => $('#drawer').classList.add('hidden')); $('.drawer-backdrop').addEventListener('click', () => $('#drawer').classList.add('hidden')); $('#threshold').addEventListener('input', (event) => $('#threshold-output').textContent = event.target.value); $('#settings-form').addEventListener('submit', async (event) => { event.preventDefault(); try { await api('/api/settings', {method:'PUT', body:JSON.stringify(settingsPayload())}); $('#settings-message').textContent = 'Preferences saved.'; } catch (error) { $('#settings-message').textContent = error.message; } }); $('#test-email').addEventListener('click', async () => { $('#settings-message').textContent = 'Sending…'; try { await api('/api/notifications/test', {method:'POST'}); $('#settings-message').textContent = 'Test email sent.'; } catch (error) { $('#settings-message').textContent = error.message; } }); $('#new-rule').addEventListener('click', () => { $('#rules').insertAdjacentHTML('afterbegin', ruleEditor()); bindRuleEvents(); }); $('#sample-btn').addEventListener('click', async () => { await api('/api/dev/sample', {method:'POST'}); await loadFeed(); }); $('#author-classification-filter').addEventListener('change', () => loadAuthors().catch(console.error)); $('#refresh-authors').addEventListener('click', () => loadAuthors().catch(console.error)); $('#registry-form').addEventListener('submit', async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); await api('/api/aggregator-registry', {method:'POST', body:JSON.stringify(Object.fromEntries(form.entries()))}); event.currentTarget.reset(); await loadRegistry(); });
document.querySelectorAll('.tab[data-view="listings"]').forEach((tab) => tab.addEventListener('click', async () => { try { await Promise.all([loadListings(true), loadBoards(true), loadDiscoveryJobs()]); } catch (error) { $('#listings').innerHTML = `<div class="empty"><p>${esc(error.message)}</p></div>`; } }));
['listing-sort','listing-provider','listing-status','listing-employment-type','listing-seniority','listing-salary-currency','listing-location-fit','listing-work-mode','listing-employer','listing-location','listing-min-salary','listing-max-age'].forEach((id) => $(`#${id}`).addEventListener('change', () => loadListings(true).catch((error) => alert(error.message))));
['listing-employer','listing-location','listing-min-salary','listing-max-age'].forEach((id) => $(`#${id}`).addEventListener('keydown', (event) => { if (event.key === 'Enter') loadListings(true).catch((error) => alert(error.message)); }));
$('#refresh-listings').addEventListener('click', async () => { try { await loadDepartments(); await Promise.all([loadListings(), loadBoards(), loadDiscoveryJobs()]); } catch (error) { console.error(error); } });
