$('#market-search').addEventListener('keydown', (event) => { if (event.key === 'Enter') loadMarket().catch((error) => alert(error.message)); });
$('#market-trend-dimension').addEventListener('change', () => loadMarketTrends().catch(console.error));
$('#market-trend-cohort').addEventListener('change', () => loadMarketTrends().catch(console.error));
$('#market-compare-button').addEventListener('click', () => loadMarketComparison().catch((error) => alert(error.message)));
$('#back-to-companies').addEventListener('click', () => { showView('companies'); loadCompanies().catch(console.error); });
['company-sort','company-provider','company-specialty','company-remote','company-contract','company-directory-prospect-status'].forEach((id) => $(`#${id}`).addEventListener('change', () => loadCompanies(true).catch(console.error)));
$('#company-search').addEventListener('keydown', (event) => { if (event.key === 'Enter') loadCompanies(true).catch((error) => alert(error.message)); });
$('#toggle-board-form').addEventListener('click', () => $('#board-form').classList.toggle('hidden'));
$('#cancel-board').addEventListener('click', () => $('#board-form').classList.add('hidden'));
$('#board-form').addEventListener('submit', async (event) => { event.preventDefault(); try { await api('/api/job-boards', {method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget).entries()))}); event.currentTarget.reset(); event.currentTarget.classList.add('hidden'); await loadBoards(); await loadListings(); } catch (error) { alert(error.message); } });
$('#discover-boards').addEventListener('click', async () => { $('#discovery-status').textContent = 'ATS discovery queued…'; try { await api('/api/listing-discovery/jobs', {method:'POST', body:JSON.stringify({mode:'full', providers:['greenhouse','ashby','lever']})}); await loadDiscoveryJobs(); } catch (error) { $('#discovery-status').textContent = error.message; } });
setInterval(() => { if ($('#view-listings').classList.contains('active')) loadDiscoveryJobs().catch(console.error); if ($('#view-polling').classList.contains('active')) loadPollTasks().catch(console.error); }, 5000);
Promise.all([loadListings(true), loadBoards(true), loadDiscoveryJobs(), loadSettings()]).then(connectEvents).catch((error) => { $('#listings').innerHTML = `<div class="empty"><p>${esc(error.message)}</p><p class="subtle">Check the server logs and database connection.</p></div>`; });
